import { isPathMatchingRoute } from './isPathMatchingRoute.js'

// built-in view keys that are handled by dedicated routes, never as custom views
const builtInViewKeys = ['edit', 'list']

/**
 * Finds the matching custom collection view for the current URL.
 *
 * Strips the `adminRoute` prefix from the current route, then iterates over the
 * collection's configured views — skipping the built-in `edit` and `list` keys —
 * and returns the first view whose resolved path (`baseRoute` + `view.path`)
 * matches the current route.
 */
export const getCustomCollectionViewByRoute = ({
  adminRoute,
  baseRoute,
  currentRoute: currentRouteWithAdmin,
  views,
}: {
  adminRoute: string
  baseRoute: string
  currentRoute: string
  views: SanitizedCollectionConfig['admin']['components']['views'] | undefined
}): {
  view: { payloadComponent?: PayloadComponent<AdminViewServerProps> }
  viewKey: null | string
} => {
  if (!views || typeof views !== 'object') {
    return {
      view: {},
      viewKey: null,
    }
  }

  const currentRoute =
    adminRoute === '/' ? currentRouteWithAdmin : currentRouteWithAdmin.replace(adminRoute, '')

  let matchedKey: null | string = null
  let matchedComponent: PayloadComponent<AdminViewServerProps> | undefined

  for (const [key, view] of Object.entries(views)) {
    if (builtInViewKeys.includes(key)) {
      continue
    }

    // only consider entries that are actually custom views with a path + component
    if (!view || typeof view.path !== 'string' || !view.Component) {
      continue
    }

    const isMatching = isPathMatchingRoute({
      currentRoute,
      exact: view.exact,
      path: `${baseRoute}${view.path}`,
      sensitive: view.sensitive,
      strict: view.strict,
    })

    if (isMatching) {
      matchedKey = key
      matchedComponent = view.Component as PayloadComponent<AdminViewServerProps>
      break
    }
  }

  if (!matchedKey) {
    return {
      view: {},
      viewKey: null,
    }
  }

  return {
    view: {
      payloadComponent: matchedComponent,
    },
    viewKey: matchedKey,
  }
}
